import random, itertools
# A reproducible quantum risk score for each asset, built from the inputs of 1.3 to 1.6. DEMO DATA: invented assets.
# score = 100 * (w1*algorithm + w2*sensitivity + w3*lifetime + w4*exposure + w5*criticality), each factor in [0, 1].
# A factor that is UNKNOWN is not replaced by 0.5: the asset gets status "insufficient evidence" and is ranked separately.
FACTORS = ("algorithm", "sensitivity", "lifetime", "exposure", "criticality")
WEIGHTS = {"algorithm": 0.25, "sensitivity": 0.20, "lifetime": 0.25, "exposure": 0.15, "criticality": 0.15}
assets = {
    "claims upload (RSA transport)":  dict(algorithm=1.0, sensitivity=1.0, lifetime=1.0, exposure=0.8, criticality=0.8),
    "customer portal (ECDHE-P256)":   dict(algorithm=0.7, sensitivity=0.7, lifetime=0.4, exposure=1.0, criticality=0.8),
    "backup wrap key (RSA-2048)":     dict(algorithm=1.0, sensitivity=1.0, lifetime=0.9, exposure=0.5, criticality=0.6),
    "admin console (ECDHE-P256)":     dict(algorithm=0.7, sensitivity=0.4, lifetime=0.1, exposure=0.2, criticality=0.6),
    "mobile API (X25519MLKEM768)":    dict(algorithm=0.1, sensitivity=0.7, lifetime=0.5, exposure=1.0, criticality=0.7),
    "HR SaaS (vendor, unverified)":   dict(algorithm=None, sensitivity=0.7, lifetime=1.0, exposure=0.5, criticality=0.4),
}
def score(a, weights=WEIGHTS):
    if any(a[f] is None for f in FACTORS):
        return None
    return 100 * sum(weights[f] * a[f] for f in FACTORS)
print("DEMO DATA. weights:", WEIGHTS)
scored = {n: score(a) for n, a in assets.items()}
print(f"{'asset':<34} {'score':>7}  band")
def band(s):
    return "insufficient evidence" if s is None else "high" if s >= 70 else "medium" if s >= 45 else "low"
for n, s in sorted(scored.items(), key=lambda kv: (kv[1] is None, -(kv[1] or 0))):
    print(f"{n:<34} {('%.1f' % s) if s is not None else '-':>7}  {band(s)}")
# sensitivity analysis: do the rankings survive plausible disagreement about the weights?
known = [n for n, s in scored.items() if s is not None]
base_rank = sorted(known, key=lambda n: -scored[n])
random.seed(11)
changes = 0
trials = 5000
top_counts = {n: 0 for n in known}
for _ in range(trials):
    w = {f: WEIGHTS[f] * random.uniform(0.5, 1.5) for f in FACTORS}
    t = sum(w.values())
    w = {f: v / t for f, v in w.items()}
    rank = sorted(known, key=lambda n: -score(assets[n], w))
    top_counts[rank[0]] += 1
    if rank != base_rank:
        changes += 1
print()
print(f"weights perturbed by up to +/-50 percent (renormalised), {trials} trials: the full ranking changed in {100 * changes / trials:.1f}% of trials")
print("share of trials in which each asset was ranked first:")
for n, c in sorted(top_counts.items(), key=lambda kv: -kv[1]):
    print(f"  {n:<34} {100 * c / trials:5.1f}%")
print()
print("the output is a prioritisation aid with stated assumptions, not a measurement of probability; the unverified vendor stays outside the ranking until its algorithm is known")
